// Un árbol binario: cada nodo guarda un valor y, como mucho, un hijo izquierdo y uno derecho
class Nodo {
  constructor(valor, izq = null, der = null) {
    this.valor = valor;
    this.izq = izq;
    this.der = der;
  }
}

//          8
//        /   \
//       3     10
//      / \      \
//     1   6      14
//        / \    /
//       4   7  13
const raiz =
  new Nodo(8,
    new Nodo(3, new Nodo(1), new Nodo(6, new Nodo(4), new Nodo(7))),
    new Nodo(10, null, new Nodo(14, new Nodo(13))));

// Los tres recorridos en profundidad difieren solo en CUÁNDO se visita el nodo
function preorden(n, salida = []) {
  if (n === null) return salida;     // un árbol vacío no tiene nada que visitar
  salida.push(n.valor);              // 1) el nodo
  preorden(n.izq, salida);           // 2) todo el lado izquierdo
  preorden(n.der, salida);           // 3) todo el lado derecho
  return salida;
}
function inorden(n, salida = []) {
  if (n === null) return salida;
  inorden(n.izq, salida);            // 1) todo el lado izquierdo
  salida.push(n.valor);              // 2) el nodo
  inorden(n.der, salida);            // 3) todo el lado derecho
  return salida;
}
function postorden(n, salida = []) {
  if (n === null) return salida;
  postorden(n.izq, salida);          // 1) todo el lado izquierdo
  postorden(n.der, salida);          // 2) todo el lado derecho
  salida.push(n.valor);              // 3) el nodo, al final
  return salida;
}
// Por niveles: en vez de la pila de llamadas, una cola (FIFO)
function porNiveles(raiz) {
  const salida = [], cola = [raiz];
  while (cola.length > 0) {
    const n = cola.shift();          // sale el que esperó más
    if (n === null) continue;
    salida.push(n.valor);
    cola.push(n.izq, n.der);         // sus hijos entran al final de la fila
  }
  return salida;
}

// Altura en niveles: cuántos nodos tiene el camino más largo de la raíz a una hoja
function altura(n) {
  if (n === null) return 0;
  return 1 + Math.max(altura(n.izq), altura(n.der));
}
function contar(n) {
  return n === null ? 0 : 1 + contar(n.izq) + contar(n.der);
}

console.log("preorden   :", preorden(raiz).join(" "));
console.log("inorden    :", inorden(raiz).join(" "));
console.log("postorden  :", postorden(raiz).join(" "));
console.log("por niveles:", porNiveles(raiz).join(" "));
console.log("nodos:", contar(raiz), "| altura:", altura(raiz), "niveles");

// Árbol binario de búsqueda: a la izquierda va lo menor, a la derecha lo mayor
class Nodo { constructor(clave) { this.clave = clave; this.izq = null; this.der = null; } }

class ArbolBusqueda {
  constructor() { this.raiz = null; }

  insertar(clave) {
    const nuevo = new Nodo(clave);
    if (this.raiz === null) { this.raiz = nuevo; return; }
    let actual = this.raiz;
    while (true) {                                   // bajar como si se buscara...
      if (clave < actual.clave) {
        if (actual.izq === null) { actual.izq = nuevo; return; }   // ...y colgar el nodo en el primer lugar vacío
        actual = actual.izq;
      } else {
        if (actual.der === null) { actual.der = nuevo; return; }
        actual = actual.der;
      }
    }
  }

  // Cuántas comparaciones hizo y si encontró la clave
  buscar(clave) {
    let actual = this.raiz, comparaciones = 0;
    while (actual !== null) {
      comparaciones++;
      if (clave === actual.clave) return { encontrada: true, comparaciones };
      actual = clave < actual.clave ? actual.izq : actual.der;   // cada decisión descarta un subárbol entero
    }
    return { encontrada: false, comparaciones };
  }

  // Altura contando por niveles, sin recursión (más abajo se ve por qué)
  altura() {
    let nivel = this.raiz === null ? [] : [this.raiz], niveles = 0;
    while (nivel.length > 0) {
      niveles++;
      const siguiente = [];
      for (const n of nivel) { if (n.izq) siguiente.push(n.izq); if (n.der) siguiente.push(n.der); }
      nivel = siguiente;
    }
    return niveles;
  }
}

// Los mismos 2.000 números, en dos órdenes de llegada
const N = 2000;
const ordenados = Array.from({ length: N }, (_, i) => i + 1);
const mezclados = [...ordenados];
for (let i = mezclados.length - 1; i > 0; i--) {        // mezcla de Fisher-Yates
  const j = Math.floor(Math.random() * (i + 1));
  [mezclados[i], mezclados[j]] = [mezclados[j], mezclados[i]];
}

for (const [nombre, orden] of [["llegan ordenados", ordenados], ["llegan mezclados", mezclados]]) {
  const a = new ArbolBusqueda();
  for (const x of orden) a.insertar(x);
  console.log(nombre.padEnd(18), "altura:", String(a.altura()).padStart(4), "| buscar", N, "->", a.buscar(N).comparaciones, "comparaciones");
}
console.log("Altura mínima posible para 2.000 nodos:", Math.ceil(Math.log2(N + 1)), "niveles");

// 1) Un árbol de expresión, armado a mano (así lo guarda un compilador por dentro; el de verdad lo ves en otro día)
const num = n => ({ tipo: "num", valor: n });
const op = (signo, izq, der) => ({ tipo: "op", signo, izq, der });

const a = op("+", num(2), op("*", num(3), num(4)));    // 2 + 3 * 4
const b = op("*", op("+", num(2), num(3)), num(4));    // (2 + 3) * 4

// Postorden: para calcular un nodo hacen falta primero sus dos hijos
function evaluar(n) {
  if (n.tipo === "num") return n.valor;
  const x = evaluar(n.izq), y = evaluar(n.der);
  return n.signo === "+" ? x + y : x * y;
}
// Inorden con paréntesis: reconstruye el texto
function texto(n) {
  return n.tipo === "num" ? String(n.valor) : "(" + texto(n.izq) + " " + n.signo + " " + texto(n.der) + ")";
}
console.log(texto(a), "=", evaluar(a));
console.log(texto(b), "=", evaluar(b));

// 2) Un depósito como árbol: depósito > pasillos > racks > pallets (pesos en kg, inventados para el ejemplo)
const deposito = {
  nombre: "Depósito", hijos: [
    { nombre: "Pasillo A", hijos: [
      { nombre: "Rack A1", hijos: [{ nombre: "pallet 1", kg: 420 }, { nombre: "pallet 2", kg: 380 }] },
      { nombre: "Rack A2", hijos: [{ nombre: "pallet 3", kg: 510 }] }
    ] },
    { nombre: "Pasillo B", hijos: [
      { nombre: "Rack B1", hijos: [{ nombre: "pallet 4", kg: 275 }, { nombre: "pallet 5", kg: 300 }, { nombre: "pallet 6", kg: 150 }] }
    ] }
  ]
};
// Postorden otra vez: el peso de un rack, de un pasillo o del depósito se conoce recién cuando se sumó todo lo que tiene adentro
function pesoTotal(nodo, profundidad = 0) {
  const kg = nodo.hijos ? nodo.hijos.reduce((suma, h) => suma + pesoTotal(h, profundidad + 1), 0) : nodo.kg;
  console.log("  ".repeat(profundidad) + nodo.nombre + ": " + kg + " kg");
  return kg;
}
pesoTotal(deposito);

// Un árbol degenerado: 100.000 nodos, cada uno con un solo hijo (una lista enlazada disfrazada)
class Nodo { constructor(valor) { this.valor = valor; this.izq = null; this.der = null; } }
const raiz = new Nodo(0);
let ultimo = raiz;
for (let i = 1; i < 100000; i++) { ultimo.der = new Nodo(i); ultimo = ultimo.der; }

// Versión recursiva: cada nivel del árbol es un marco más en la pila de llamadas
function alturaRecursiva(n) {
  return n === null ? 0 : 1 + Math.max(alturaRecursiva(n.izq), alturaRecursiva(n.der));
}
// Versión por niveles, sin recursión
function alturaPorNiveles(raiz) {
  let nivel = [raiz], niveles = 0;
  while (nivel.length > 0) {
    niveles++;
    const siguiente = [];
    for (const n of nivel) { if (n.izq) siguiente.push(n.izq); if (n.der) siguiente.push(n.der); }
    nivel = siguiente;
  }
  return niveles;
}

try {
  console.log("recursiva:", alturaRecursiva(raiz));
} catch (e) {
  console.log("recursiva falló:", e.name);     // el mensaje exacto cambia según el navegador
}
console.log("por niveles:", alturaPorNiveles(raiz));
